refused_program.body:
set -e
renames=$(git ls-files -z | tr '\0' '\n' | grep -E '(^|/)renames[^/]*\.conf$' | head -n1)
[ -n "$renames" ]
map=$(mktemp)
tmp=$(mktemp)
trap 'rm -f "$map" "$tmp"' EXIT
awk '
  /^[[:space:]]*#/ { next }
  /^[[:space:]]*$/ { next }
  {
    eq=index($0,"=")
    if (eq == 0) next
    old=substr($0,1,eq-1); new=substr($0,eq+1)
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", old)
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", new)
    sub(/[[:space:]]+#.*$/, "", new)
    if (old != "" && new != "" && old != new) printf "%s\t%s\n", old, new
  }
' "$renames" > "$map"
while IFS= read -r f; do
  case "$f" in
    config/*|*.conf|*.ini|*.cfg) ;;
    *) continue ;;
  esac
  [ -f "$f" ] || continue
  if awk -F'\t' '
    NR==FNR { if (NF>=2) old[$1]=1; next }
    {
      eq=index($0,"=")
      if (eq == 0) next
      key=substr($0,1,eq-1)
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", key)
      if (key in old) { found=1; exit }
    }
    END { exit(found ? 0 : 1) }
  ' "$map" "$f"; then
    awk -F'\t' '
      NR==FNR { if (NF>=2) new[$1]=$2; next }
      {
        line=$0
        eq=index(line,"=")
        if (eq == 0) { print line; next }
        left=substr(line,1,eq-1)
        right=substr(line,eq)
        key=left
        gsub(/^[[:space:]]+|[[:space:]]+$/, "", key)
        if (key in new) {
          lead=left
          sub(/[^[:space:]].*$/, "", lead)
          trail=left
          sub(/^.*[^[:space:]]/, "", trail)
          print lead new[key] trail right
        } else {
          print line
        }
      }
    ' "$map" "$f" > "$tmp"
    cat "$tmp" > "$f"
  fi
done < <(git ls-files --others --ignored --exclude-standard -z | tr '\0' '\n')

preconditions.probe:
renames=$(git ls-files -z | tr '\0' '\n' | grep -E '(^|/)renames[^/]*\.conf$' | head -n1)
[ -n "$renames" ] || exit 1
awk '
  /^[[:space:]]*#/ { next }
  /^[[:space:]]*$/ { next }
  {
    eq=index($0,"=")
    if (eq == 0) next
    old=substr($0,1,eq-1); new=substr($0,eq+1)
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", old)
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", new)
    sub(/[[:space:]]+#.*$/, "", new)
    if (old != "" && new != "" && old != new) found=1
  }
  END { exit(found ? 0 : 1) }
' "$renames"
